class Solution {
public:
    vector<int> parent, r;

    int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    void unite(int x, int y) {
        int px = find(x), py = find(y);
        if (px == py) return;
        if (r[px] < r[py]) {
            int t = px; px = py; py = t;
        }
        parent[py] = px;
        if (r[px] == r[py]) r[px]++;
    }

    vector<bool> areConnected(int n, int threshold, vector<vector<int>>& queries) {
        parent.resize(n + 1);
        r.resize(n + 1, 0);
        for (int i = 0; i <= n; i++) parent[i] = i;

        if (threshold == 0) {
            return vector<bool>(queries.size(), true);
        }

        for (int d = threshold + 1; d <= n; d++) {
            for (int m = d + d; m <= n; m += d) {
                unite(d, m);
            }
        }

        vector<bool> result;
        result.reserve(queries.size());
        for (auto& q : queries) {
            result.push_back(find(q[0]) == find(q[1]));
        }
        return result;
    }
};
